using System;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;
public class TradePreset {public string id,title;public string[] source_titles;public int sea,cost;public Dictionary<string,int> sells,buys;public override string ToString(){return title;}}
public class MergedCity : City {public bool playable;public int[] terrain_ids;public TradePreset[] trade_presets;public string default_trade_id;}
public class MergedCatalog {public int template;public MergedCity[] cities;}
public class AssignmentChoice {public int slot;public string label;public override string ToString(){return label;}}
partial class ScenarioCreator {
 MergedCatalog merged;ComboBox tradePresetPicker=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=238};Label tradeSummary=new Label{Dock=DockStyle.Fill};ToolTip tradeTip=new ToolTip();
 static string SerializeProject(Scenario data){var value=Json.Deserialize<Dictionary<string,object>>(Json.Serialize(data));if(string.IsNullOrWhiteSpace(data.briefing))value.Remove("briefing");CleanStartMessage(value,data);CleanPlayerGoals(value);ApplyThroneToFile(value);ApplyMinPlayersToFile(value);ApplyMakerToolsToFile(value);foreach(var slot in (System.Collections.IEnumerable)value["slots"]){var record=(Dictionary<string,object>)slot;if(record["starting_setup"]==null)record.Remove("starting_setup");if(record["terrain_asset"]==null)record.Remove("terrain_asset");if(record["governance"]==null)record.Remove("governance");if(record["events"]==null)record.Remove("events");else foreach(var ev in (System.Collections.IEnumerable)record["events"]){var row=ev as Dictionary<string,object>;if(row!=null)foreach(var key in new[]{"text","when","repeat"})if(row.ContainsKey(key)&&row[key]==null)row.Remove(key);}if(record["invasions"]==null)record.Remove("invasions");else foreach(var attack in (System.Collections.IEnumerable)record["invasions"]){var row=attack as Dictionary<string,object>;if(row!=null&&row.ContainsKey("enemy")&&row["enemy"]==null)row.Remove("enemy");if(row!=null&&row.ContainsKey("repeat")&&row["repeat"]==null)row.Remove("repeat");}if(record["invasion_enemy"]==null)record.Remove("invasion_enemy");if(record["starting_funds"]==null)record.Remove("starting_funds");if(record["role_hint"]==null)record.Remove("role_hint");}var empireRecord=(Dictionary<string,object>)value["empire"];if(empireRecord["route_paths"]==null||((Dictionary<string,object>)empireRecord["route_paths"]).Count==0)empireRecord.Remove("route_paths");else foreach(var path in ((Dictionary<string,object>)empireRecord["route_paths"]).Values){var record=(Dictionary<string,object>)path;if(record["data"]==null)record.Remove("data");}foreach(var city in (System.Collections.IEnumerable)((Dictionary<string,object>)value["empire"])["cities"]){var record=(Dictionary<string,object>)city;if(record["trade_players"]==null)record.Remove("trade_players");CleanCityRecord(record);}return Json.Serialize(value);}
 // Optional parts are left out of the file when empty: the game refuses a null or an unknown city (scenario_project.py).
 static void CleanStartMessage(Dictionary<string,object> value,Scenario data){
  var m=data.start_message;var record=new Dictionary<string,object>();
  if(m!=null&&!string.IsNullOrWhiteSpace(m.common))record["common"]=m.common.Replace("\r\n","\n");
  if(m!=null&&m.per_city!=null){var per=new Dictionary<string,object>();foreach(var p in m.per_city)if(!string.IsNullOrWhiteSpace(p.Value)&&data.slots!=null&&data.slots.Any(s=>s.id==p.Key))per[p.Key]=p.Value.Replace("\r\n","\n");if(per.Count>0)record["per_city"]=per;}
  if(record.Count==0)value.Remove("start_message");else value["start_message"]=record;
 }
 static void CleanPlayerGoals(Dictionary<string,object> value){
  object rules,goals;if(!value.TryGetValue("rules",out rules)||!(rules is Dictionary<string,object>))return;
  if(!((Dictionary<string,object>)rules).TryGetValue("objectives",out goals)||!(goals is Dictionary<string,object>))return;
  var record=(Dictionary<string,object>)goals;object table;
  if(record.TryGetValue("by_players",out table)&&(table==null||((Dictionary<string,object>)table).Count==0))record.Remove("by_players");
 }
 void MergeMissingCities(Scenario data){var all=data.empire.cities.ToList();foreach(var city in merged.cities)if(!all.Any(c=>c.name_id==city.name_id))all.Add(new City{name_id=city.name_id,x=city.x,y=city.y,role="npc",enabled=false,sea=city.sea,cost=city.cost,sells=new Dictionary<string,int>(city.sells),buys=new Dictionary<string,int>(city.buys)});data.empire.cities=all.ToArray();data.empire.template=25;}
 void LoadMerged(){merged=Json.Deserialize<MergedCatalog>(RunPython("creator_presets.py","--merged"));catalogPlayable=new HashSet<int>(merged.cities.Where(c=>c.playable).Select(c=>c.name_id));map.PlayableCities=new HashSet<int>(catalogPlayable);}
 // Green on the map: a city whose game map ships with Caesar III (the catalog), or one that carries a map of its own in THIS
 // project (a neutral city's attached map, a seat's imported map). Worked out again each time (2026-11-15: a city given a map
 // stayed green in the next project or after its map was gone, and assigning it then failed with "지형 자료를 찾지 못했습니다").
 HashSet<int> catalogPlayable=new HashSet<int>();
 void SyncPlayable(){if(map==null)return;   /* an editor object made without its window (handoff/Regression.cs) has no map to colour */
  var set=catalogPlayable==null?new HashSet<int>(map.PlayableCities):new HashSet<int>(catalogPlayable);if(project!=null&&project.empire!=null){foreach(var c in project.empire.cities)if(c.map!=null)set.Add(c.name_id);if(project.slots!=null)foreach(var s in project.slots)if(s.terrain_asset!=null)set.Add(s.name_id);}foreach(int id in ShelfCities())set.Add(id);   /* the author's map shelf (CreatorCityLibrary.cs) */if(!set.SetEquals(map.PlayableCities)){map.PlayableCities=set;map.Invalidate();}}
 bool HasTerrain(int name){SyncPlayable();if(project!=null&&project.empire.cities.Any(c=>c.name_id==name&&c.reserved))return false;return map.PlayableCities.Contains(name);}
 bool LocalAvailableTerrain(int name){return presets.terrain.Any(t=>t.name_id==name&&t.available);}
 MissionPreset[] CityTerrains(int name){return presets.terrain.Where(t=>t.available&&t.name_id==name).ToArray();}
 int PreferredTerrain(int name){var choices=CityTerrains(name);if(choices.Length==0)throw new Exception("이 도시의 지형 자료를 현재 본편 폴더에서 찾지 못했습니다. 시저 3 본편과 공식 지도 파일을 확인해 주세요.");return choices.FirstOrDefault(t=>t.id>=2&&t.id<100)==null?choices[0].id:choices.First(t=>t.id>=2&&t.id<100).id;}
 void PopulateAssignment(City city){cityIdentity.Items.Clear();int own=Array.FindIndex(project.slots,s=>s.name_id==city.name_id);if(!HasTerrain(city.name_id)&&own<0){cityIdentity.Items.Add(new AssignmentChoice{slot=-2,label="중립 교역도시 · 플레이 지형 없음"});cityIdentity.SelectedIndex=0;cityIdentity.Enabled=false;return;}cityIdentity.Enabled=true;cityIdentity.Items.Add(new AssignmentChoice{slot=-1,label="플레이어 배정 안 함"});for(int i=0;i<project.slots.Length;i++)cityIdentity.Items.Add(new AssignmentChoice{slot=i,label="P"+(i+1)+" 도시로 배정 · "+CityName(project.slots[i].name_id)});cityIdentity.SelectedIndex=own>=0?own+1:0;}
 void ChangeCityIdentity(){var choice=cityIdentity.SelectedItem as AssignmentChoice;if(choice==null||choice.slot==-2)return;StoreCity();var target=project.empire.cities[selected];int own=Array.FindIndex(project.slots,s=>s.name_id==target.name_id);if(choice.slot<0){if(own>=0){RemovePlayer();if(selected>=0)ShowCity(selected);}return;}if(own==choice.slot)return;if(own>=0){ShowCity(selected);throw new Exception("이 도시는 이미 P"+(own+1)+"에 배정되어 있습니다. 다른 초록 도시를 선택해 주세요.");}if(!HasTerrain(target.name_id))throw new Exception("플레이 지형이 있는 초록 도시만 배정할 수 있습니다.");var slot=project.slots[choice.slot];if((slot.terrain_edits!=null&&slot.terrain_edits.Length>0)||slot.terrain_asset!=null){if(LangBox.Show(this,"P"+(choice.slot+1)+"의 도시를 바꾸면 이전 도시의 지형과 수정 내용은 그 도시에 보관되고, 이 자리는 새 도시의 지형을 씁니다. 허용 건물과 통치 설정은 이 자리에 그대로 남습니다. 바꿀까요?","플레이어 도시 변경",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes){ShowCity(selected);return;}}AssignCity(choice.slot,target.name_id);}
 void AssignCity(int index,int name){if(!HasTerrain(name))throw new Exception("이 도시에는 플레이할 지형이 없습니다.");var keeper=Array.Find(project.empire.cities,c=>c.name_id==name);var shelf=keeper!=null&&keeper.map!=null?null:ShelfMapFor(name);   /* no map in this scenario nor in the game: the newest on the shelf */int terrainId=keeper!=null&&keeper.map!=null?keeper.map.campaign_scenario:shelf!=null?SafeBase(name,shelf.base_preset):PreferredTerrain(name);/* a kept (parked) map must also exist in this game folder, unless it carries its own imported terrain */if(keeper!=null&&keeper.map!=null&&keeper.map.terrain_asset==null){var keptTerrain=Array.Find(presets.terrain,t=>t.id==terrainId);if(keptTerrain==null||!keptTerrain.available)throw new Exception("이 도시의 지형 자료를 현재 본편 폴더에서 찾지 못했습니다. 시저 3 본편과 공식 지도 파일을 확인해 주세요.");}var slot=project.slots[index];var old=Array.Find(project.empire.cities,c=>c.name_id==slot.name_id);var next=Array.Find(project.empire.cities,c=>c.name_id==name);if(next==null)throw new Exception("통합 지도에 없는 도시입니다.");if(project.slots.Where((p,i)=>i!=index).Any(p=>p.name_id==name))throw new Exception("이미 다른 플레이어 자리에서 사용하는 도시입니다.");old.role="npc";old.enabled=false;ParkPlayerCity(old,slot);ParkNeutralTrade(next);slot.name_id=name;slot.campaign_scenario=terrainId;slot.terrain_edits=new TerrainEdit[0];slot.terrain_asset=null;if(next.map!=null){RestoreParked(slot,next.map);NoteKeptSettings(slot,next.map);next.map=null;}if(shelf!=null)slot.terrain_asset=new TerrainAsset{format=shelf.terrain_asset.format,sha256=shelf.terrain_asset.sha256,data=shelf.terrain_asset.data};nativeSessions.Remove(slot.id);nativePreviews.Remove(slot.id);next.role="player";next.enabled=true;next.sea=next.cost=0;next.sells.Clear();next.buys.Clear();selected=-1;RefreshCities();SelectCity(name);Changed();}
 void RestoreDefaultTrade(City city){var metadata=Array.Find(merged.cities,c=>c.name_id==city.name_id);var policy=metadata==null?null:metadata.trade_presets.FirstOrDefault(p=>p.id==metadata.default_trade_id);if(policy==null){city.sea=city.cost=0;city.sells=new Dictionary<string,int>();city.buys=new Dictionary<string,int>();return;}city.sea=policy.sea;city.cost=policy.cost;city.sells=new Dictionary<string,int>(policy.sells);city.buys=new Dictionary<string,int>(policy.buys);}
 static bool SameAmounts(Dictionary<string,int> a,Dictionary<string,int>b){return a!=null&&b!=null&&a.Count==b.Count&&a.All(p=>b.ContainsKey(p.Key)&&b[p.Key]==p.Value);}
 void PopulateTrade(City city){tradePresetPicker.Items.Clear();var metadata=Array.Find(merged.cities,c=>c.name_id==city.name_id);if(metadata!=null)foreach(var policy in metadata.trade_presets)tradePresetPicker.Items.Add(policy);int match=-1;for(int i=0;i<tradePresetPicker.Items.Count;i++){var p=(TradePreset)tradePresetPicker.Items[i];if(p.sea==city.sea&&p.cost==city.cost&&SameAmounts(p.sells,city.sells)&&SameAmounts(p.buys,city.buys)){match=i;break;}}if(match<0){tradePresetPicker.Items.Add(new TradePreset{id="custom",title="사용자 설정"});match=tradePresetPicker.Items.Count-1;}tradePresetPicker.SelectedIndex=match;tradePresetPicker.Enabled=city.role=="npc";ShowTradeSummary(city);}
 void ShowTradeSummary(City city){if(city.sells.Count==0&&city.buys.Count==0)tradeSummary.Text="교역 품목: 없음";else tradeSummary.Text="이 도시에서 사오기 "+city.sells.Count+"종 · 이 도시에 팔기 "+city.buys.Count+"종";var selected=tradePresetPicker.SelectedItem as TradePreset;tradeTip.SetToolTip(tradePresetPicker,selected!=null&&selected.source_titles!=null?string.Join("\n",selected.source_titles):"품목과 거래량을 직접 수정할 수 있습니다.");}
 void ApplyTradePreset(){if(selected<0||project.empire.cities[selected].role!="npc")return;var policy=tradePresetPicker.SelectedItem as TradePreset;if(policy==null||policy.id=="custom")return;var city=project.empire.cities[selected];city.sea=policy.sea;city.cost=policy.cost;city.sells=new Dictionary<string,int>(policy.sells);city.buys=new Dictionary<string,int>(policy.buys);ShowCity(selected);Changed();}
}
